import { siteConfig } from "@/config/site";

function SiteFooter() {
  return (
    <footer className="border-border border-t">
      <div className="text-muted-foreground mx-auto flex max-w-[1280px] flex-col items-center gap-6 px-6 py-8.5 text-[13px] sm:flex-row md:px-10">
        <span className="mr-auto flex items-center gap-2.5">
          <span className="flex gap-0.75">
            <span className="bg-primary h-4.5 w-2.25" />
            <span className="h-4.5 w-2.25 border border-current" />
          </span>
          <span className="font-heading text-foreground text-base tracking-wide">
            {siteConfig.name.toUpperCase()}
          </span>
        </span>
        <span className="font-mono text-xs">1 builds · 0 breaks</span>
        <span className="font-mono text-xs">{siteConfig.contactEmail}</span>
      </div>
    </footer>
  );
}

export { SiteFooter };
